var names=new[]{"Wand_Weapon","Garlic_Weapon","Whip_Weapon","Axe_Weapon","Bible_Weapon","Cross_Weapon"};var lines=new System.Collections.Generic.List<string>();foreach(var name in names){var path="Assets/Prefabs/Weapons/"+name+".prefab";var root=UnityEditor.AssetDatabase.LoadAssetAtPath<UnityEngine.GameObject>(path);if(!root){lines.Add(path+" NOT FOUND");continue;}lines.Add(path);foreach(var t in root.GetComponentsInChildren<UnityEngine.Transform>(true))lines.Add("  "+t.name+" components="+string.Join(",",t.GetComponents<UnityEngine.Component>().Where(c=>c!=null).Select(c=>c.GetType().Name)));}return string.Join("\n",lines);
